// Demo: Signature Code Embeddings — k-NN neighborhood
var pts=[];for(var i=0;i<1;i++){pts.push({id:i,x:((i*37+1)%100),y:((i*53)%100)});}
var q={x:50,y:50};
var nb=pts.map(function(p){return {id:p.id,d:Math.hypot(p.x-q.x,p.y-q.y)};}).sort(function(a,b){return a.d-b.d;}).slice(0,5);
console.log('technique: Signature Code Embeddings');console.log('query at (50,50), nearest: '+nb.map(function(n){return n.id+'('+n.d.toFixed(1)+')';}).join(', '));

