// Demo: Signature HDBSCAN Clustering — silhouette-style cohesion
var clusters=[[10,12,11],[80,82,79]];
function mean(a){return a.reduce(function(x,y){return x+y;},0)/a.length;}
var cohesion=clusters.map(function(c){var m=mean(c);return Math.sqrt(c.reduce(function(s,v){return s+(v-m)*(v-m);},0)/c.length);});
console.log('technique: Signature HDBSCAN Clustering');console.log('cluster spreads: '+cohesion.map(function(c){return c.toFixed(1);}).join(', '));
console.log('tight clusters — good separation');

